// ADAAAA-8318 (ADAAAA-8302 Option 2, contract addendum to v9): the clip card's
// COPY TARGET is a short post title, not the announcer line.
//
// Two copy surfaces now ship on a highlight:
//
//   postTitle  — <= 60 chars / <= 10 words, ONE clause, no colour beat, no
//                place chain, no clock prefix, no trailing period. This is what
//                the card seeds the "Suggested caption" / "Use as caption"
//                affordance with. Generated by the SAME decide pass as the
//                announcer line (no second inference), gated here at the write
//                seam, and projected for every row at read time.
//   caption    — the announcer play-by-play line ratified by ADAAAA-7933
//                (<= 110 target / 140 hard max, `MAX_CAPTION_CHARS` 180). It is
//                UNCHANGED by this contract; the card renders it as collapsed
//                "What happened" detail.
//
// A row whose model title is absent (every legacy row, and every VOD row — the
// VOD long-form prompt is byte-identical and emits no title) gets a
// DETERMINISTIC title derived only from stored facts:
//
//     GOAL · 1:12 · Real Madrid
//     SHOT · 1:49
//     BIG PLAY · 4:21
//
// The deterministic path is a pure function: no model call at read time, no
// invented names, never empty, never a mid-word truncation. Both the server
// projection and the webapp card read the SAME function, so a served title can
// never disagree with a rendered one.
import {
  attestationDetailCopy,
  captionSourceText,
  captionSourceViolation,
  gateGoalClaims,
  gateAbsenceClaims,
  groundNames,
  hasGoalClaim,
  hasPlacePhrase,
  humanEventLabel,
  stripInternalTokens,
  ROLE_NOUN_FORM_ALT,
  type CaptionGroundingContext,
} from "./caption-grounding";

/** The measured target: a social post title, not a description. */
export const POST_TITLE_TARGET_CHARS = 60;
/** Hard reject bar — a title longer than this is dropped to the deterministic one. */
export const POST_TITLE_HARD_MAX_CHARS = 70;
/** One clause, ten words. */
export const POST_TITLE_MAX_WORDS = 10;
/** The deterministic fallback's own ceiling (`GOAL · 1:12 · Real Madrid` = 26). */
export const FALLBACK_TITLE_MAX_CHARS = 40;

/**
 * Label vocabulary. A title opens on the EVENT, uppercase, with no `T+` clock
 * (the clock is its own segment) and no taxonomy token leaking through
 * (`SPORTING_EVENT` is a code, "BIG PLAY" is copy).
 */
const TITLE_LABELS: Record<string, string> = {
  GOAL: "GOAL",
  SCORING_PLAY: "GOAL",
  PENALTY: "GOAL",
  NEAR_MISS: "NEAR MISS",
  BIG_PLAY: "BIG PLAY",
  SPORTING_EVENT: "BIG PLAY",
  SHOT: "SHOT",
  SAVE: "SAVE",
  TACKLE: "TACKLE",
  CELEBRATION: "CELEBRATION",
  HIGHLIGHT: "HIGHLIGHT",
};

const OUTCOME_LABELS: Record<string, string> = {
  scoring_play: "GOAL",
  near_miss: "NEAR MISS",
  big_play: "BIG PLAY",
  not_highlight: "HIGHLIGHT",
};

/**
 * The title's leading label. The stored eventType wins (it is the board-facing
 * taxonomy the verdict produced); the outcome taxonomy is the fallback, and an
 * unknown/long event type degrades to a human label rather than an enum.
 */
export function postTitleLabel(eventType?: string | null, outcome?: string | null): string {
  const et = (eventType ?? "").trim().toUpperCase().replace(/[\s-]+/g, "_");
  const oc = (outcome ?? "").trim().toLowerCase();
  const eventLabel = TITLE_LABELS[et];
  // ADAAAA-8645 (measured on the served build, job `f02ec0bf` row `85a89562`): a
  // row keeps its stored `eventType` ("GOAL") when the read seam demotes it — the
  // demotion is a projection (`outcome: "big_play"`), never a rewrite of the
  // stored row. Deriving the label from the taxonomy alone therefore served
  // "GOAL · 1:40" on a row the dive REFUTED, i.e. the deterministic fallback
  // asserted the very claim the read seam's own S2 rule refuses
  // (`servedPostTitleViolations`: no goal claim when the stored verdict is not
  // `scoring_play`). The served verdict wins over the stored taxonomy, so the
  // label obeys the same rule the claim gate applies.
  if (eventLabel === "GOAL" && oc && oc !== "scoring_play") {
    const downgraded = OUTCOME_LABELS[oc];
    if (downgraded && downgraded !== "GOAL") return downgraded;
  }
  if (eventLabel) return eventLabel;
  if (OUTCOME_LABELS[oc]) return OUTCOME_LABELS[oc];
  if (et) {
    const human = humanEventLabel(et).toUpperCase();
    // A label is a token or two, never a sentence: cap at two words.
    const words = human.split(/\s+/).slice(0, 2).join(" ");
    if (words && words.length <= 16) return words;
  }
  return "HIGHLIGHT";
}

/** `m:ss` for the clip's window instant; "" when the row carries no usable ts. */
export function postTitleClock(seconds?: number | null): string {
  const t = typeof seconds === "number" && Number.isFinite(seconds) && seconds >= 0 ? Math.floor(seconds) : null;
  if (t === null) return "";
  const mins = Math.floor(t / 60);
  const secs = t % 60;
  return `${mins}:${String(secs).padStart(2, "0")}`;
}

/** Collapse whitespace and strip the punctuation a title never ends on. */
function tidyTitle(text: string): string {
  return text
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[\s,;:.!?—–-]+$/, "")
    .trim();
}

/**
 * The DETERMINISTIC title: `LABEL · m:ss [· SUBJECT]`.
 *
 * `subject` is optional and must already be a stored fact about THIS row — a
 * team from the job's `matchContext` that the row's own copy names, or a player
 * the row's gated copy names. It is dropped (never cut mid-word) when it would
 * push the title past `FALLBACK_TITLE_MAX_CHARS`, so the function always returns
 * a non-empty, word-clean title.
 */
export function deterministicPostTitle(input: {
  eventType?: string | null;
  outcome?: string | null;
  windowTs?: number | null;
  subject?: string | null;
}): string {
  return composePostTitle({
    label: postTitleLabel(input.eventType, input.outcome),
    windowTs: input.windowTs,
    subject: input.subject,
  });
}

/**
 * ADAAAA-8910: `LABEL · m:ss [· SUBJECT]` for a label the caller already
 * resolved (the write seam stores this shape so a non-asserting title is a
 * STORED fact, not only a read-time fallback). Same budget and same subject
 * rules as `deterministicPostTitle`, which delegates here.
 */
export function composePostTitle(input: {
  label: string;
  windowTs?: number | null;
  subject?: string | null;
}): string {
  // The label is from the closed label vocabulary (`GOAL`, `BIG PLAY`, …), never
  // a sentence: `stripInternalTokens` would delete a leading all-caps word and
  // turn `GOAL` into an empty segment, so only the SUBJECT is stripped.
  const label = tidyTitle((input.label ?? "").trim()) || "HIGHLIGHT";
  const clock = postTitleClock(input.windowTs);
  const subject = tidyTitle(stripInternalTokens((input.subject ?? "").trim()));
  const build = (withSubject: boolean): string =>
    [label, clock, withSubject ? subject : ""].filter(Boolean).join(" · ");
  // A subject is a name, not a sentence: anything over a handful of words (or
  // over the budget with the label + clock) is not a usable segment.
  const usableSubject =
    !!subject && subject.split(/\s+/).length <= 4 && subject.length <= 24;
  if (usableSubject) {
    const withSubject = build(true);
    if (withSubject.length <= FALLBACK_TITLE_MAX_CHARS) return withSubject;
  }
  const bare = build(false);
  if (bare.length <= FALLBACK_TITLE_MAX_CHARS) return bare;
  // Only reachable with an absurd label: the label alone is still a title.
  return label.slice(0, FALLBACK_TITLE_MAX_CHARS).trim();
}


/** EVERY reason a candidate title may not be served as customer copy. */
export type PostTitleViolation =
  | "empty"
  | "too-long"
  | "too-many-words"
  | "second-clause"
  | "place-chain"
  | "clock-prefix"
  | "internal-token"
  | "goal-claim"
  | "absence-claim"
  /** ADAAAA-8831 (AC9/AC10): the title asserts an action with no attested
   *  ACTOR — a bare role-noun subject (`Midfielder scores`) or a score/ball
   *  claim that names nobody. */
  | "unattested-actor"
  | "ungrounded-name";

const CLOCK_PREFIX = /^T\s*\+\s*(?:\d{1,3}:\d{2}|\d+(?:\.\d+)?\s*s)\b[\s·:—–-]*/i;
/** A second clause: an em/en dash continuation, a semicolon, or a sentence break. */
const SECOND_CLAUSE = /[—–]|;\s|\.\s+(?=[A-ZÀ-Ý"'(])/u;

/**
 * Strip what is PUNCTUATION rather than content: internal evidence tokens, a
 * leading `T+12s —` clock prefix, and the trailing period a title never ends on.
 * This is a clean, not a rewrite — a violation survives it and is still refused.
 */
export function cleanPostTitle(text?: string | null): string {
  const raw = (text ?? "").trim();
  if (!raw) return "";
  let out = stripInternalTokens(raw).replace(/\s+/g, " ").trim();
  out = out.replace(CLOCK_PREFIX, "").trim();
  out = tidyTitle(out);
  return out;
}

/**
 * The SHAPE bar alone (no evidence gates): what a read-time projection can check
 * on a stored title without the window's prompt.
 */
export function postTitleShapeViolations(text: string): PostTitleViolation[] {
  const title = (text ?? "").trim();
  if (!title) return ["empty"];
  const out: PostTitleViolation[] = [];
  if (title.length > POST_TITLE_HARD_MAX_CHARS) out.push("too-long");
  if (title.split(/\s+/).length > POST_TITLE_MAX_WORDS) out.push("too-many-words");
  if (SECOND_CLAUSE.test(title)) out.push("second-clause");
  if (hasPlacePhrase(title)) out.push("place-chain");
  if (CLOCK_PREFIX.test(title) || /^T\s*\+/i.test(title)) out.push("clock-prefix");
  if (stripInternalTokens(title) !== title) out.push("internal-token");
  return out;
}

/**
 * A place phrase at the END of a title (the AC2 "place chain" shape the model
 * keeps emitting: "Player carries ball in midfield", "Foul in the middle
 * third"). Kept next to the title bar so an extractive trim can never drift
 * from the read-time shape check (`hasPlacePhrase`).
 */
const TITLE_TRAILING_PLACE = new RegExp(
  String.raw`\b(?:in|at|from|near|inside|outside|around|on|into)\s+(?:the\s+)?` +
    String.raw`(?:penalty\s+area|box|goal\s+area|six[- ]yard\s+box|` +
    String.raw`cent(?:er|re)(?:\s+(?:circle|field|area))?|midfield|middle\s+third|final\s+third|` +
    String.raw`attacking\s+third|defensive\s+third|near\s+post|far\s+post|close\s+range|` +
    String.raw`touchline|wing|halves?|half|edge\s+of\s+the\s+(?:box|area)|left|right)\b\.?$`,
  "iu"
);

/**
 * EXTRACTIVE shape repair (ADAAAA-8356): strip a trailing place phrase and a
 * second clause off a candidate title, deleting text only — never rewriting,
 * never inventing. Used ONLY when the raw title fails the shape bar, and the
 * result must pass every bar the raw form is held to (shape AND the evidence
 * gates), so a claim or an unsourced name survives the trim and is still
 * refused. A title that cannot be repaired this way is refused as before (the
 * card falls back to the deterministic `LABEL · m:ss` title).
 */
export function trimPostTitleShape(text?: string | null): string {
  let out = cleanPostTitle(text);
  if (!out) return "";
  for (let pass = 0; pass < 3; pass++) {
    const before = out;
    // a second clause after a dash, semicolon or sentence break
    const lead = out.split(/\s+[—–]\s+|;\s+|\.\s+(?=[A-ZÀ-Ý"'(])/u)[0] ?? out;
    out = tidyTitle(lead);
    out = tidyTitle(out.replace(TITLE_TRAILING_PLACE, ""));
    if (out === before) break;
  }
  return out;
}

/**
 * A title that already appears on this job's cards is a REPEAT, not copy
 * (ADAAAA-8356 AC6: 23 distinct titles over 25 cards). Session-scoped at the
 * write seam: the caller passes the titles already stored for this job, and a
 * duplicate is dropped so the read projection derives the deterministic
 * `LABEL · m:ss` title instead — distinct by construction, no extra inference.
 */
export function uniquePostTitle(
  title?: string | null,
  used: readonly (string | null | undefined)[] = []
): string | null {
  const cleaned = cleanPostTitle(title);
  if (!cleaned) return null;
  const key = cleaned.toLowerCase();
  for (const other of used) {
    if (cleanPostTitle(other).toLowerCase() === key) return null;
  }
  return cleaned;
}

/**
 * The WRITE-SEAM gate (v9 grounding, reused): shape + the evidence rules the
 * announcer line already crosses — a goal claim only on a scoring verdict, no
 * absence claim without evidence, names only from the window's own prompt, no
 * internal tokens. Returns the clean title, or `null` when the candidate must
 * fall back to the deterministic title. A refusal is never a partially rewritten
 * title: a half-gated claim is worse than an honest fallback.
 *
 * ADAAAA-8356: when the raw title fails the SHAPE bar only, the extractive
 * `trimPostTitleShape` form is offered as a second candidate and must still pass
 * every evidence gate. That is a deletion, not a rewrite — the measured defect
 * was 46/54 rows refused because a model title ended "... in midfield".
 */
export function gatePostTitleValue(
  raw: string | null | undefined,
  ctx?: CaptionGroundingContext
): string | null {
  return gatePostTitleDetail(raw, ctx).title;
}

/** What the write seam did with a candidate title, as one audit token. */
export type PostTitleGate =
  | "absent"
  | "accepted"
  /** accepted only after the extractive `trimPostTitleShape` deletion */
  | "trimmed"
  /** ADAAAA-8910: the candidate was a bare label, or was refused ONLY by
   *  claim-shaped bars, so the deterministic NON-ASSERTING label title serves
   *  (`GOAL · 1:42`). `label:<bars>` keeps the attribution of the refused
   *  candidate; a bare `label` means the model itself emitted the label. */
  | "label"
  | `label:${string}`
  /** refused: the candidate (and its trimmed form) failed these bars */
  | `refused:${string}`;


export interface PostTitleGateDecision {
  /** The value the write seam may store; null => the deterministic title serves. */
  title: string | null;
  /** Audit token persisted beside the row: prompt-vs-gate attribution. */
  gate: PostTitleGate;
  /** Every bar the raw title failed (shape + evidence, union of both candidates). */
  violations: PostTitleViolation[];
}

/** The shape of a title whose SUBJECT is a bare role noun (`Midfielder scores`,
 *  `The defender clears it`). The role vocabulary is the one the body gate
 *  attests against (`caption-grounding`), so a title and a body can never
 *  disagree about which words are role nouns. A jersey number (`No. 7 scores`)
 *  is not a role noun: it is a legible actor, so it is unaffected. */
const TITLE_ROLE_SUBJECT = new RegExp(
  String.raw`^\s*(?:(?:the|a|an)\s+)?(?:${ROLE_NOUN_FORM_ALT})\b`,
  "iu"
);

/** A LABEL-only title (`GOAL · 1:42`) is the deterministic fallback itself: it
 *  asserts the event label the row's own verdict already certifies, never an
 *  actor's action, so it must stay serveable rather than be re-derived. */
const LABEL_ONLY_TITLE = new RegExp(
  String.raw`^\s*(?:${[...new Set(Object.values(TITLE_LABELS))].join("|")})(?:\s*·\s*\d{1,3}:\d{2})?\s*$`,
  "iu"
);

/** ADAAAA-8910: a title that is ONLY the event label (`GOAL`, `BIG PLAY`), with
 *  no clock segment. The write seam stores the clocked form (`GOAL · 1:42`) so a
 *  non-asserting title is distinct per row and carries the row's own instant. */
export function isBareLabelTitle(title?: string | null): boolean {
  const t = (title ?? "").trim();
  if (!t || !LABEL_ONLY_TITLE.test(t)) return false;
  return !/·/.test(t);
}

/** Every label the closed vocabulary can emit, so a stored `LABEL · m:ss` is
 *  recognised by the LABEL and not by its shape alone. */
const POST_TITLE_LABELS: ReadonlySet<string> = new Set([
  ...Object.values(TITLE_LABELS),
  ...Object.values(OUTCOME_LABELS),
]);

/** ADAAAA-8910: the STORED `LABEL · m:ss [· subject]` form the write seam emits.
 *
 *  `cleanPostTitle` is the read seam's normaliser and it deletes both halves of
 *  this shape — the label is an all-caps internal token and the clock is a
 *  provenance token — so a stored label title would otherwise serve as a bare
 *  `1:42`. The composed shape is therefore read BEFORE cleaning, and only when
 *  the label is in the closed vocabulary. */
export function isComposedLabelTitle(title?: string | null): boolean {
  const t = (title ?? "").trim();
  const match = t.match(/^([A-Z][A-Z ]{0,19}?)\s*·\s*\d{1,3}:\d{2}(?:\s*·\s*.+)?$/u);
  if (!match) return false;
  return POST_TITLE_LABELS.has((match[1] ?? "").trim());
}

/** ADAAAA-8910: the violations that a NON-ASSERTING label title satisfies without
 *  inventing anything. A candidate refused only by these bars is not dropped:
 *  the deterministic `LABEL · m:ss` title serves instead (live job `9bed3bd7`
 *  served 0/5 titles `refused:unattested-actor` on a job whose own match context
 *  attests two teams, because the FAST prompt asks for `WHO + VERB` while the
 *  actor bar refuses every role noun — the contradiction, measured). */
export const LABEL_DEGRADABLE_VIOLATIONS: readonly PostTitleViolation[] = [
  "unattested-actor",
  "goal-claim",
];

/**
 * ADAAAA-8831 (AC9/AC10): the title asserts an action with NO attested actor.
 *
 * Live leg `27bd816f` served `Midfielder scores` / `Defender scores` on rows
 * whose attested evidence was `[clock, score, action]` with
 * `actors=["Barcelona"]` and `bodyNamesAttestedActor=false`: a role noun is not a
 * name, so neither the write seam's name gate nor the read seam's S3 had anything
 * to refuse, and the card's headline credited a score to nobody.
 *
 * The bar is the measured SHAPE: a title whose subject is a bare role noun. A
 * role noun is an attestation claim (`SUMMARY_ROLE_NOUN_GROUPS`, the same table
 * the AC10 body neutraliser uses) and a six-to-ten-word headline carries no
 * evidence for it. Such a title is refused at BOTH seams, so the card serves the
 * deterministic non-asserting title (`GOAL · 1:42`, or `GOAL · 1:42 · Barcelona`
 * when the row's own copy names exactly one of the match's teams) — never an
 * invented actor.
 *
 * What is NOT claimed here: a subjectless claim (`Scores from close range`) still
 * passes, because the shipped name gate reads a sentence-initial capital as a
 * possible proper name. The role-noun shape is what the leg measured, and adding
 * a second verb/name lexicon to catch the rest is a product decision, not a
 * silent widening. A title that DOES name its actor (`No. 7 scores`, `Barcelona
 * midfielder scores`) is unaffected: its name still clears the same provenance
 * gate (`ungrounded-name`).
 */
export function postTitleActorMissing(title: string): boolean {
  const t = (title ?? "").trim();
  if (!t) return false;
  if (LABEL_ONLY_TITLE.test(t)) return false;
  return TITLE_ROLE_SUBJECT.test(t);
}

/**
 * Every reason THIS candidate may not be served, shape AND evidence.
 *
 * Shape is the bar the read projection re-checks on stored values; evidence is
 * the bar only the write seam can run (it owns this window's prompt and verdict).
 */
export function postTitleViolations(title: string, ctx?: CaptionGroundingContext): PostTitleViolation[] {
  const out = postTitleShapeViolations(title);
  // ADAAAA-8831 (AC9/AC10): an action with no attested actor is not copy, at
  // either seam — a title can be perfectly SHAPED and still credit a score to a
  // role noun nobody measured.
  if (postTitleActorMissing(title)) out.push("unattested-actor");
  if (ctx) {
    if (hasGoalClaim(title) && gateGoalClaims(title, ctx) !== title) out.push("goal-claim");
    if (gateAbsenceClaims(title, ctx) !== title) out.push("absence-claim");
    if (groundNames(title, ctx.promptText) !== title) out.push("ungrounded-name");
    // ADAAAA-8411 (writer residue from the Phase D grade): prompt grounding alone
    // accepts a name the window's TRANSCRIPT mentions on a DIFFERENT play — the
    // measured class was `Manuel Ordoñez scores` / `Ordoña scores` where the ASR
    // names the player in a save and the headline attributes the score. A
    // headline's names are now held to the row's OWN copy, the same bar the READ
    // seam already applies to a stored title (`servedPostTitleViolations`, S3), so
    // the two seams can no longer disagree about who a card names.
    if (typeof ctx.ownCopy === "string" && ctx.ownCopy.trim() && groundNames(title, ctx.ownCopy) !== title) {
      out.push("ungrounded-name");
    }
  }
  return out;
}

/**
 * ADAAAA-8356 (PO acceptance addendum, constraint 1): the SAME gate, but it
 * names its decision.
 *
 * Phase B measured the defect classes on a build whose PROMPT already asked for
 * the clean shape (341/898 place chains, 24/898 second beats, 39 goal claims on
 * non-scoring verdicts), so prompt wording alone is not the fix — the writer
 * must deterministically reject or repair, and the row must carry WHY. The
 * `gate` token makes the next grade attribute a residual without another paid
 * leg: `absent` is a prompt miss (the model emitted no title), `refused:*` is a
 * gate refusal (the model emitted a title the bars refuse), `trimmed` is the
 * extractive repair, `accepted` is model copy served as written.
 */
export function gatePostTitleDetail(
  raw: string | null | undefined,
  ctx?: CaptionGroundingContext,
  /** ADAAAA-8910: the deterministic NON-ASSERTING label title for this row
   *  (`GOAL`), supplied by the caller that owns the row's verdict. When present,
   *  a candidate the claim bars refuse is not dropped: the label serves and the
   *  gate token names WHY (`label:<bars>`). Absent => today's refusal. */
  opts?: { label?: string | null }
): PostTitleGateDecision {
  const direct = cleanPostTitle(raw);
  if (!direct) return { title: null, gate: "absent", violations: ["empty"] };
  const trimmed = trimPostTitleShape(raw);
  const candidates: { title: string; trimmed: boolean }[] =
    trimmed && trimmed !== direct
      ? [
          { title: direct, trimmed: false },
          { title: trimmed, trimmed: true },
        ]
      : [{ title: direct, trimmed: false }];
  const refused: PostTitleViolation[] = [];
  for (const candidate of candidates) {
    if (!candidate.title) continue;
    const violations = postTitleViolations(candidate.title, ctx);
    if (violations.length === 0) {
      // ADAAAA-8910: the model emitted the bare label itself — the surface wants
      // the clocked `LABEL · m:ss` form, so the caller composes it and the token
      // says the served title is the label, not model prose.
      return {
        title: candidate.title,
        gate: isBareLabelTitle(candidate.title) ? "label" : candidate.trimmed ? "trimmed" : "accepted",
        violations: [],
      };
    }
    for (const violation of violations) if (!refused.includes(violation)) refused.push(violation);
  }
  const label = (opts?.label ?? "").trim();
  if (label && refused.every((v) => LABEL_DEGRADABLE_VIOLATIONS.includes(v))) {
    return { title: label, gate: `label:${refused.join(",")}`, violations: refused };
  }
  return { title: null, gate: `refused:${refused.join(",")}`, violations: refused };
}


/** The fields the projection needs from a stored highlight row. */
export interface PostTitleRow {
  postTitle?: string | null;
  caption?: string | null;
  reason?: string | null;
  /** ADAAAA-8405 (S3): the audit copy the write seam preserved when it refused
   * the model's sentence — part of "the row's own copy". */
  reasonRaw?: string | null;
  eventType?: string | null;
  outcome?: string | null;
  localizedTs?: number | null;
  start?: number | null;
}

/** The row's OWN copy — the only evidence a read-time gate has. */
export function postTitleRowCopy(row: PostTitleRow): string {
  return [row.postTitle, row.caption, row.reason, row.reasonRaw]
    .map((v) => (v ?? "").trim())
    .filter(Boolean)
    .join(" \n ");
}

/**
 * ADAAAA-8405 (PO ruling 2026-11-08, ship bar S1-S3/S5): the READ-SEAM bar.
 *
 * The write seam refuses a title it cannot gate, but a row written BEFORE that
 * gate existed still carries such a title — measured on the 13 post-deploy
 * rows: 3 served `David Saez scores` where the row's copy names Carlos Javier,
 * and 7 more rows refused `goal-claim` at write time. The card is the customer
 * surface, so the projection re-checks the stored value against the facts the
 * row itself carries:
 *
 *   - the shape bar (S1 place chain, S5 length/words/`T+`), as before;
 *   - S2: no score/goal claim when the STORED verdict is not `scoring_play`;
 *   - S3: every person/team name in the title must occur, as a whole phrase, in
 *     the row's own copy (`postTitle`/`caption`/`reason`/`reasonRaw`).
 *
 * This is a TIGHTENING of the read gate, never a loosening: a title that passes
 * is one the write gate would also accept, and a title that fails serves the
 * deterministic `LABEL · m:ss` fallback instead.
 */
export function servedPostTitleViolations(title: string, row: PostTitleRow): PostTitleViolation[] {
  const out = postTitleShapeViolations(title);
  // ADAAAA-8831 (AC9/AC10): the live leg's served titles were shaped fine and
  // named nobody (`Midfielder scores`), so the read seam applies the actor bar
  // too — the card is the customer surface, and the deterministic
  // `LABEL · m:ss` title is the fallback.
  if (postTitleActorMissing(title)) out.push("unattested-actor");
  const verdict = (row.outcome ?? "").trim().toLowerCase();
  if (verdict && verdict !== "scoring_play" && hasGoalClaim(title)) out.push("goal-claim");
  const copy = postTitleRowCopy({ ...row, postTitle: null });
  // No copy at all is NOT evidence against the title: a row whose only stored
  // text is the title was already gated by the write seam against this window's
  // prompt, and the read path has nothing to contradict it. The check fires only
  // when the row carries copy that does not name what the title names.
  if (copy.trim() && groundNames(title, copy) !== title) out.push("ungrounded-name");
  return out;
}

/**
 * The title a surface SERVES for a row.
 *
 * A stored `postTitle` is trusted only while it still satisfies the shape bar
 * (the write seam already ran the evidence gates, and the read path has no
 * prompt to re-run them). A row with no title, or a stored value that fails the
 * bar, gets the deterministic title — never an empty string, never a silent
 * mid-word cut.
 */
export function projectPostTitle(
  row: PostTitleRow,
  opts?: { subject?: string | null }
): string {
  const rawStored = (row.postTitle ?? "").trim();
  // ADAAAA-8910: the write seam's own non-asserting form is served verbatim —
  // cleaning it would strip the label and then the clock (see
  // `isComposedLabelTitle`). The claim bars still apply, and `internal-token` is
  // exactly the shape this bar expects, so it is the one violation ignored.
  if (rawStored && isComposedLabelTitle(rawStored)) {
    const composedViolations = servedPostTitleViolations(rawStored, row).filter((v) => v !== "internal-token");
    if (composedViolations.length === 0) return rawStored;
  }
  const stored = cleanPostTitle(row.postTitle);
  if (stored && servedPostTitleViolations(stored, row).length === 0) {
    // ADAAAA-8910: a stored BARE label (`GOAL`) is the non-asserting title the
    // write seam degrades to; the surface composes the row's own clock (and the
    // subject its own copy names) so the label form never loses the `m:ss`
    // segment the deterministic projection has always served.
    if (isBareLabelTitle(stored)) {
      return composePostTitle({
        label: stored,
        windowTs: postTitleRowTs(row),
        subject: opts?.subject ?? null,
      });
    }
    return stored;
  }
  const windowTs = postTitleRowTs(row);
  return deterministicPostTitle({
    eventType: row.eventType,
    outcome: row.outcome,
    windowTs,
    subject: opts?.subject ?? null,
  });
}

/** The row's own clip instant, read the way every surface reads it. */
function postTitleRowTs(row: PostTitleRow): number | null {
  return typeof row.localizedTs === "number" && Number.isFinite(row.localizedTs)
    ? row.localizedTs
    : typeof row.start === "number" && Number.isFinite(row.start)
      ? row.start
      : null;
}

/** ADAAAA-8910: the value the write seam STORES for a non-asserting label.
 *
 *  `uniquePostTitle` answers the duplicate question but returns the CLEANED value,
 *  and cleaning a `LABEL · m:ss` title deletes the label (an internal all-caps
 *  token) and then the clock — so a seam that stored its return would store a bare
 *  `1:42`. This composes the form the write seam stores, composes the collision
 *  key the same way the existing guard does, and reports both. */
export function storedLabelTitle(input: {
  label: string;
  windowTs?: number | null;
  subject?: string | null;
  /** The titles already stored for this job. */
  used?: readonly (string | null | undefined)[];
}): { title: string | null; composed: string; duplicate: boolean } {
  const composed = composePostTitle({ label: input.label, windowTs: input.windowTs, subject: input.subject });
  const duplicate = uniquePostTitle(composed, input.used ?? []) === null;
  return { title: duplicate ? null : composed, composed, duplicate };
}

/**
 * The collapsed ANNOUNCER detail a surface SERVES for a row (ADAAAA-8405 S4).
 *
 * The write seam stores `caption` from the row's own gated announcer sentence
 * (`storedSurfaceFor`: `card.caption || storedReason`), so a row written after
 * that change always carries detail copy. A row written BEFORE it stores
 * `reason` and no `caption`, and the detail route used to fall back to the post
 * TITLE — measured on the 20 stored rows: 6 of 10 postable cards served
 * `caption == postTitle`, which is a headline, not announcer copy.
 *
 * The read path therefore mirrors the seam: a row with no stored caption serves
 * its own gated `reason` — the same string the fixed seam would have stored.
 * Nothing is invented and no gate is bypassed: `reason` is the sentence the
 * write seam already certified for this row and already serves on it. A row
 * whose only copy is the audit `reasonRaw` (which never crossed the gates) gets
 * no caption from the audit line, so the deterministic title stays the last
 * resort exactly as before.
 */
export function projectAnnouncerCaption(row: PostTitleRow, servedTitle: string): string {
  // ADAAAA-8830: the READ gate mirrors the write gate. A row stored before
  // ADAAAA-8830 can carry the model's SCORING-LANE sentence as its `caption`
  // and/or `reason` — the window audit marker (`at t=0.0`, `at t=-1.0s`, the
  // match clock `t=22:13`, the bare settler `at 18:12`) and the `ASR confirms …`
  // citation are provenance, never copy (live leg `27bd816f` rows
  // `8d521507`/`a4827973` served them verbatim). `captionSourceViolation` is the
  // same bar `storedReasonViolations` applies at the write seam, so the two
  // surfaces cannot disagree: such a row falls through to the row's own attested
  // fact sentence below — never to `reason_raw` prose.
  //
  // ADAAAA-8806: every caption source strips the CAPTION-ONLY diagnostic tails
  // (`| provisional goal:`, `| provisional shot:`, the `| live scoring lane:`
  // refusal paragraph) before serving. A legacy row stores that marker on its
  // `reason` on purpose (ADAAAA-8139 keeps it as the audit value), so serving
  // `reason` verbatim served the whole evidence paragraph as the card's copy —
  // measured on the 10-day corpus: 4 rows (`1f965fea`, `ccab232a`, `61e9439a`,
  // `74deffd0`). `captionSourceText` is the same strip the write seam applies, so
  // the strip stays ONE definition; a clean stored row is byte-identical.
  const stored = captionSourceText(row.caption ?? "").trim();
  if (stored && captionSourceViolation(stored) === "") return stored;
  const own = captionSourceText(row.reason ?? "").trim();
  // Never serve a caption byte-identical to the title: that is the degrade the
  // bar exists to catch, so a `reason` that repeats the title is not detail.
  if (own && own !== servedTitle.trim() && captionSourceViolation(own) === "") return own;
  // ADAAAA-8411: a row whose ONLY model sentence is a clock-bracketed
  // attestation line (`Scoreboard changes to 2-2 at t=-3.3s and ASR confirms 'il
  // gol!'`) stores no `reason` at all — the store-time post-condition refuses the
  // audit marker. The row still OWES detail copy, so the same fact sentence the
  // write seam derives is derived here from the row's own audit line: deletion
  // only (attestation clauses and the marker dropped), gated, and — with no
  // prompt at read time — a scoreline is served only on a row whose stored
  // verdict is `scoring_play`. Measured: this is the ONE holdout of the Phase D
  // FAIL (row f4407757, card `GOAL · 2:38`).
  // ADAAAA-8830: a legacy row whose `caption`/`reason` was refused by the
  // caption-source bar often has NO `reason_raw` — the seam omits it when the
  // stored line IS the model's line (row `8d521507` on leg `27bd816f`). Its own
  // stored `reason` is the same sentence, so it is the deletion lane's source
  // here: extractive only, the marker and the citation deleted, every gate and
  // the store-time post-condition unchanged (measured on the 10-day corpus:
  // 92 of 500 stored rows serve evidence prose; without this they would degrade
  // to the bare fact line while a fresh row of the same shape serves the ledger
  // sentence — a store/served shape disagreement).
  const evidence = (row.reasonRaw ?? "").trim() || own;
  if (evidence) {
    const fact = attestationDetailCopy(evidence, { verdict: row.outcome ?? null, eventType: row.eventType ?? null });
    // Never serve the refused string back as its own "derivation".
    if (fact && fact !== servedTitle.trim() && fact !== stored && fact !== own) return fact;
  }
  // ADAAAA-8411: the announcer line may never degrade to the headline, so a
  // postable row with no honest model copy at all (nothing stored, nothing
  // derivable) still serves a FACT sentence from its own stored facts: the
  // verdict label the row itself carries and its own window instant — never a
  // claim the row did not store, never a name, never the title. The title stays
  // the last resort for a row with no instant at all (a non-postable shape).
  const facts = storedFactAnnouncerCopy(row, servedTitle);
  if (facts) return facts;
  return servedTitle;
}

/**
 * ADAAAA-8411: the deterministic FACT sentence a row serves when it has no
 * honest model copy — `<verdict label> at <m:ss>.` from the row's OWN stored
 * verdict and window instant.
 *
 * It exists so the card's "What happened" line can never be byte-identical to
 * its headline. Nothing is invented: the label is the row's own stored verdict
 * (the `outcome` taxonomy wins over `eventType`, so a DEMOTED goal never asserts
 * "Goal"), the instant is the row's own window start/localized stamp, and the
 * sentence adds no name, no score and no goal claim the row did not store.
 * `""` when the row carries no usable instant — the caller then keeps the title.
 */
export function storedFactAnnouncerCopy(row: PostTitleRow, servedTitle: string): string {
  const windowTs =
    typeof row.localizedTs === "number" && Number.isFinite(row.localizedTs)
      ? row.localizedTs
      : typeof row.start === "number" && Number.isFinite(row.start)
        ? row.start
        : null;
  const clock = postTitleClock(windowTs);
  if (!clock) return "";
  const outcome = (row.outcome ?? "").trim().toLowerCase();
  // The OUTCOME taxonomy governs a non-scoring row (a demoted goal is a
  // `big_play`, never "Goal"); only a scoring row may carry its eventType label.
  const label = postTitleLabel(outcome === "scoring_play" ? row.eventType : null, row.outcome);
  // The label vocabulary is uppercase (it opens a title); a sentence opens on a
  // capital and continues lowercase (`Goal at 2:38.`, `Near miss at 5:00.`).
  const sentenceLabel = label.charAt(0) + label.slice(1).toLowerCase();
  const sentence = `${sentenceLabel} at ${clock}.`;
  if (sentence.trim() === servedTitle.trim()) return "";
  if (outcome !== "scoring_play" && hasGoalClaim(sentence)) return "";
  return sentence;
}

/**
 * The team name a row's own stored copy names, from the job's `matchContext` —
 * the only team attribution the deterministic title may use (a stored fact, not
 * a guess about which side scored). "" when the match context is ambiguous, the
 * row names no team, or the copy names both.
 */
export function postTitleTeamSubject(
  row: PostTitleRow,
  matchContext?: { teams?: { name?: string | null }[]; ambiguous?: boolean } | null
): string {
  const teams = (matchContext?.teams ?? [])
    .map((t) => tidyTitle(t?.name ?? ""))
    .filter((name) => name.length > 0);
  if (!teams.length) return "";
  const copy = `${row.postTitle ?? ""} ${row.caption ?? ""} ${row.reason ?? ""}`;
  const norm = (s: string) =>
    s
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase();
  const named = teams.filter((name) => norm(copy).includes(norm(name)));
  return named.length === 1 ? named[0] : "";
}
